// The original visual system and service flows are retained in app.js.
const regionsV2=['서울','부산','대구','인천','광주','대전','울산','세종','경기','강원','충북','충남','전북','전남','경북','경남','제주'];
const supplyTypesV2=['공공분양','민간분양','공공임대'];
const agesV2=['10대','20대','30대','40대','50대','60대 이상'];
const regionalBoardsV2=['자유','청약·집 구하기','금융','입주 새내기','장터','동네 생활정보','자취생','친구 만들기','비밀의 화원'];
const unionBoardsV2=['자유','청약·집 구하기','금융','생활정보·꿀팁','음식·맛집','홍보·동아리','재테크','만화·애니','연극·뮤지컬','음악','스포츠','게임'];
const communityV2={scope:'지역',region:'서울',board:'자유',age:'전체 연령',search:'',sort:'최신순'};
state.posts=read('posts-v2',null)||makeExamplePostsV2();
initialPosts.splice(0,initialPosts.length,...state.posts.filter(p=>p.region==='서울').slice(0,4));
const originalHomeV2=home;
home=function(){return originalHomeV2().replace('주거, 금융생활, 커리어까지','동네 생활, 금융, 취향 이야기까지');};
const originalGuideV2=guide;
guide=function(){originalGuideV2();for(const el of document.querySelectorAll('.flow-card small'))if(el.textContent.includes('통합·주제'))el.textContent='지역·연합 게시판, HOT과 연령 필터';};
function makeExamplePostsV2(){
  const regionalTitles={'자유':'집에 돌아와서 제일 먼저 하는 일은?','청약·집 구하기':'공고문에서 먼저 확인하면 좋은 항목 공유해요','금융':'이사 예산에 빠뜨리기 쉬운 비용이 있나요?','입주 새내기':'이번 주에 이사 왔어요. 반갑습니다!','장터':'이사하며 정리하는 책상, 나눔해요','동네 생활정보':'동네 산책하기 좋은 길을 함께 찾아요','자취생':'혼자 살 때 냉장고 식재료 어떻게 관리하세요?','친구 만들기':'주말 낮에 가볍게 산책할 이웃 있나요?','비밀의 화원':'이상형은 취향이 비슷한 사람인가요?'};
  const unionTitles={'자유':'주말에 집에서 쉬기 vs 밖에서 놀기','청약·집 구하기':'처음 집을 구할 때 알았으면 좋았을 것들','금융':'주거 자금 계획, 어떤 순서로 정리하시나요?','생활정보·꿀팁':'작은 집 수납을 위한 소소한 팁','음식·맛집':'퇴근 후 15분 안에 만드는 한 끼 추천','홍보·동아리':'온라인 독서 모임, 함께 읽을 분 구해요','재테크':'고정 지출부터 점검하는 가계부 습관','만화·애니':'이번 주말 정주행할 작품 추천해 주세요','연극·뮤지컬':'처음 보는 사람에게 추천하는 공연은?','음악':'이사한 첫날 듣고 싶은 플레이리스트','스포츠':'혼자 시작하기 좋은 운동 이야기','게임':'친구와 함께하기 좋은 협동 게임 추천'};
  let n=100;const now=Date.now();const posts=[];
  for(const [ri,region] of regionsV2.entries())for(const [bi,board] of regionalBoardsV2.entries()){
    posts.push({id:n++,scope:'지역',region,board,age:agesV2[(ri+bi)%agesV2.length],job:'일반',title:regionalTitles[board],body:`${region}에서 생활하는 이웃들과 이야기하고 싶어요. 여러분의 경험과 생각을 댓글로 나눠 주세요.\n\n화면 흐름을 체험하기 위한 예시 게시글입니다.`,author:'익명 이웃',likes:5+(ri*3+bi*7)%38,comments:bi%3?[{author:'익명 새싹',body:'저도 비슷한 고민이 있어요. 같이 이야기해요.'}]:[],createdAt:now-(ri+bi+1)*3600000,time:'오늘',example:true});
  }
  for(const [bi,board] of unionBoardsV2.entries())posts.push({id:n++,scope:'연합',region:null,board,age:agesV2[bi%agesV2.length],job:'일반',title:unionTitles[board],body:'지역에 관계없이 함께 나누는 이야기입니다. 여러분의 취향과 경험이 궁금해요.\n\n화면 흐름을 체험하기 위한 예시 게시글입니다.',author:'익명 구름',likes:11+bi*3,comments:[{author:'익명 나무',body:'좋은 주제네요! 경험을 나눠 볼게요.'}],createdAt:now-(bi+1)*5400000,time:'오늘',example:true});
  return posts;
}
// Nationwide examples cover all 17 regions and each supported supply type.
// (복원 시 뺀 부분: 예시 공고 추가·진단 지역 선택·집 찾기 지역 필터 덮어쓰기. 지금은 서버 공고와 live.js가 맡는다)
function regionSelectV2(key,values,selected,label){return `<select aria-label="${label}" data-region-answer="${key}">${values.map(v=>`<option ${v===selected?'selected':''}>${v}</option>`).join('')}</select>`;}
function boardOptionsV2(){return communityV2.scope==='지역'?regionalBoardsV2:unionBoardsV2;}
function postContextV2(p){return p.scope==='지역'?`${p.region} · 지역`:'전국 · 연합';}
function likedV2(id){return read('liked-v2',[]).includes(id);}
function filteredPostsV2(){const c=communityV2;let list=state.posts.filter(p=>(c.board==='HOT 게시판'||(p.scope===c.scope&&(c.scope!=='지역'||p.region===c.region)&&p.board===c.board))&&(c.age==='전체 연령'||p.age===c.age)&&`${p.title} ${p.body}`.toLowerCase().includes(c.search.toLowerCase()));if(c.board==='HOT 게시판'){list=list.filter(p=>p.createdAt>=Date.now()-7*86400000);list.sort((a,b)=>b.likes-a.likes||b.comments.length-a.comments.length||b.createdAt-a.createdAt);}else if(c.sort==='추천순')list.sort((a,b)=>b.likes-a.likes||b.createdAt-a.createdAt);else list.sort((a,b)=>b.createdAt-a.createdAt);return list;}
community=function(){const c=communityV2,posts=filteredPostsV2(),hot=c.board==='HOT 게시판';return `<div class="wrap page reveal"><div class="page-title"><div class="eyebrow">OUR LITTLE NEIGHBORHOOD</div><h1>우리 동네부터, 모두의 이야기까지.</h1><p>이웃과 나누는 일상, 지역을 넘어 만나는 취향. 편하게 이야기해요.</p></div><div class="community-scope-v2" aria-label="커뮤니티 범위">${['지역','연합'].map(s=>`<button class="chip ${!hot&&c.scope===s?'active':''}" data-v2="scope" data-value="${s}">${s==='지역'?'지역별 게시판':'연합게시판'}</button>`).join('')}<button class="chip hot-chip-v2 ${hot?'active':''}" data-v2="board" data-value="HOT 게시판">🔥 HOT 게시판</button>${!hot&&c.scope==='지역'?`<label class="community-region-label-v2">내 지역 <select aria-label="커뮤니티 지역" data-v2-filter="region">${regionsV2.map(v=>`<option ${v===c.region?'selected':''}>${v}</option>`).join('')}</select></label>`:''}</div><div class="board-layout"><aside class="panel board-sidebar"><h3>${hot?'함께 보는 공간':c.scope==='지역'?c.region+' 게시판':'연합게시판'}</h3>${boardOptionsV2().map(b=>`<button class="board-link ${!hot&&c.board===b?'active':''}" data-v2="board" data-value="${b}">${b}</button>`).join('')}<div class="sidebar-divider-v2"></div><button class="board-link ${hot?'active':''}" data-v2="board" data-value="HOT 게시판">🔥 HOT 게시판</button><h3>게시판 이용</h3><button class="board-link" data-v2="rules">이용 안내 ↗</button></aside><section><div class="section-head"><div><h2>${esc(c.board)} <small>${posts.length}개 글</small></h2><p class="board-description-v2">${hot?'최근 7일, 지역·연합 전체의 추천 많은 이야기':c.scope==='지역'?esc(c.region)+' 이웃들의 '+esc(c.board)+' 이야기':'전국에서 함께 나누는 '+esc(c.board)+' 이야기'}</p></div><button class="btn small" data-v2="write">＋ 글쓰기</button></div><form class="search-row" id="board-search-v2"><input aria-label="게시글 검색" placeholder="궁금한 이야기 검색" value="${esc(c.search)}"><button class="btn secondary" type="submit">검색</button></form><div class="board-filter"><label>연령대 <select aria-label="연령대 필터" data-v2-filter="age">${['전체 연령',...agesV2].map(v=>`<option ${v===c.age?'selected':''}>${v}</option>`).join('')}</select></label>${!hot?`<select aria-label="게시글 정렬" data-v2-filter="sort">${['최신순','추천순'].map(v=>`<option ${v===c.sort?'selected':''}>${v}</option>`).join('')}</select>`:'<span class="hot-order-v2">추천 → 댓글 → 최신순</span>'}<button class="text-link" data-v2="clear">초기화</button></div><div class="post-list">${posts.length?posts.map(p=>`<article class="post-row"><a href="#post/${p.id}" class="post-main-v2"><div class="tags"><span class="badge gray">${esc(p.board)}</span><span class="tag">${esc(postContextV2(p))}</span><span class="tag">${esc(p.age)}</span>${p.example?'<span class="tag">예시</span>':''}</div><h3>${esc(p.title)}</h3><p>${esc(p.body.split('\n')[0])}</p><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div></a><button class="post-score like-button-v2 ${likedV2(p.id)?'liked':''}" data-v2="like" data-id="${p.id}" aria-label="${esc(p.title)} 추천 ${p.likes}" aria-pressed="${likedV2(p.id)}">👍<br><span>${p.likes}</span></button></article>`).join(''):'<div class="empty" style="border:0"><h3>아직 이 조건의 글이 없어요</h3><p>연령 필터를 바꾸거나 첫 이야기를 남겨 주세요.</p><button class="btn soft small" data-v2="clear">필터 초기화</button></div>'}</div><p class="demo-note">예시 게시글과 체험용 연령 태그입니다. 작성·추천·댓글은 현재 브라우저에만 저장됩니다.</p></section></div></div>`;};
post=function(id){const p=state.posts.find(p=>p.id===Number(id));if(!p)return emptyPage('게시글을 찾을 수 없어요','목록에서 다시 선택해 주세요.','community','목록으로');return `<div class="wrap page reveal"><div class="breadcrumbs"><a href="#community">커뮤니티</a> / ${esc(postContextV2(p))} / ${esc(p.board)}</div><article class="panel post-detail"><div class="tags"><span class="badge">${esc(p.board)}</span><span class="tag">${esc(p.age)}</span>${p.example?'<span class="tag">예시 게시글</span>':''}</div><h2>${esc(p.title)}</h2><div class="post-meta"><span>${esc(p.author)}</span><span>${p.time}</span><span>댓글 ${p.comments.length}</span></div><p class="post-content">${esc(p.body)}</p><div class="post-actions-v2"><button class="btn soft small ${likedV2(p.id)?'liked':''}" data-v2="like" data-id="${p.id}" aria-pressed="${likedV2(p.id)}">👍 ${likedV2(p.id)?'추천 취소':'추천'} ${p.likes}</button><button class="btn secondary small" data-action="report-post" data-id="${p.id}">신고</button><a href="#community" class="btn secondary small">목록으로</a></div><div class="comments"><h3>댓글 ${p.comments.length}</h3>${p.comments.map(c=>`<div class="comment"><strong>${esc(c.author)}</strong><p>${esc(c.body)}</p></div>`).join('')}<form class="reply-form" id="comment-form-v2" data-id="${p.id}"><input placeholder="이야기를 남겨 주세요" aria-label="댓글" maxlength="1000" required><button class="btn" type="submit">등록</button></form></div></article></div>`;};
function writePostV2(){requireLogin(()=>{const c=communityV2;modal(`<div class="eyebrow">SHARE YOUR STORY</div><h2>우리 이야기 남기기</h2><p>어느 공간에 남길지 선택해 주세요.</p><form id="post-form-v2"><div class="form-row"><div class="field"><label for="post-scope-v2">게시판 범위</label><select id="post-scope-v2">${['지역','연합'].map(s=>`<option ${s===c.scope?'selected':''}>${s}</option>`).join('')}</select></div><div class="field" id="write-region-field-v2"><label for="post-region-v2">지역</label><select id="post-region-v2">${regionsV2.map(r=>`<option ${r===c.region?'selected':''}>${r}</option>`).join('')}</select></div></div><div class="form-row"><div class="field"><label for="post-board-v2">게시판</label><select id="post-board-v2"></select></div><div class="field"><label for="post-age-v2">연령 태그</label><select id="post-age-v2">${agesV2.map(a=>`<option ${a==='20대'?'selected':''}>${a}</option>`).join('')}</select></div></div><div class="field"><label for="post-title-v2">제목</label><input id="post-title-v2" maxlength="80" required placeholder="함께 나누고 싶은 이야기는?"></div><div class="field"><label for="post-body-v2">내용</label><textarea id="post-body-v2" rows="5" maxlength="5000" required placeholder="실명·연락처 등 개인정보는 적지 마세요."></textarea></div><button class="btn full" type="submit">체험 글 등록 →</button><p class="demo-note">HOT은 추천을 받은 글이 모이는 공간입니다. 이 글은 현재 브라우저에 저장됩니다.</p></form>`);updateWriteBoardsV2(c.board);});}
function updateWriteBoardsV2(preferred){const scope=$('#post-scope-v2').value,values=scope==='지역'?regionalBoardsV2:unionBoardsV2;$('#post-board-v2').innerHTML=values.map(b=>`<option ${b===preferred?'selected':''}>${b}</option>`).join('');$('#write-region-field-v2').hidden=scope!=='지역';}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v2]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const v=b.dataset.value;switch(b.dataset.v2){case'scope':communityV2.scope=v;communityV2.board='자유';communityV2.search='';render();break;case'board':communityV2.board=v;render();break;case'clear':communityV2.age='전체 연령';communityV2.search='';communityV2.sort='최신순';render();break;case'write':writePostV2();break;case'like':{const id=Number(b.dataset.id),p=state.posts.find(p=>p.id===id);if(!p)return;requireLogin(()=>{const liked=read('liked-v2',[]),active=liked.includes(id);p.likes=Math.max(0,p.likes+(active?-1:1));save('liked-v2',active?liked.filter(n=>n!==id):[...liked,id]);save('posts-v2',state.posts);render();toast(active?'추천을 취소했어요.':'추천했어요.');});break;}case'rules':modal('<h2>함께 쓰는 공간의 약속</h2><p>이웃과 서로 존중하며 이야기해 주세요.</p><ul class="plain-list"><li>실명·동호수·연락처·타인의 사진을 공개하지 않아요.</li><li>장터는 개인 물품 거래, 홍보·동아리는 모임 소개에 이용해요.</li><li>금융 사기·불법 광고·혐오·괴롭힘은 신고 대상입니다.</li><li>비밀의 화원은 설렘과 연애 고민을 나누는 공간입니다.</li><li>연령 태그는 자율 선택이며 인증을 의미하지 않습니다.</li></ul><p class="demo-note">신고는 체험 화면이며 실제 운영자에게 전달되지 않습니다.</p>');break;}},true);
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.v2Filter){e.stopImmediatePropagation();communityV2[el.dataset.v2Filter]=el.value;render();}if(el.dataset.regionAnswer){e.stopImmediatePropagation();state.answers[el.dataset.regionAnswer]=el.value;}if(el.id==='post-scope-v2'){e.stopImmediatePropagation();updateWriteBoardsV2();}},true);
document.addEventListener('submit',e=>{const f=e.target;if(!['board-search-v2','post-form-v2','comment-form-v2'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();if(f.id==='board-search-v2'){communityV2.search=f.querySelector('input').value.trim();render();return;}if(f.id==='post-form-v2'){const title=$('#post-title-v2').value.trim(),body=$('#post-body-v2').value.trim();if(!title||!body){toast('제목과 내용을 입력해 주세요.');return;}const scope=$('#post-scope-v2').value,region=scope==='지역'?$('#post-region-v2').value:null,board=$('#post-board-v2').value;const p={id:Date.now(),scope,region,board,age:$('#post-age-v2').value,job:'일반',title,body,author:'익명 '+state.user.name,likes:0,comments:[],createdAt:Date.now(),time:'방금',example:false};state.posts.unshift(p);save('posts-v2',state.posts);Object.assign(communityV2,{scope,region:region||communityV2.region,board,age:'전체 연령',search:''});go('post/'+p.id);toast('이 브라우저에 글을 저장했어요.');return;}const body=f.querySelector('input').value.trim(),p=state.posts.find(p=>p.id===Number(f.dataset.id));if(!body||!p)return;requireLogin(()=>{p.comments.push({author:'익명 '+state.user.name,body});save('posts-v2',state.posts);render();toast('댓글을 저장했어요.');});},true);
const originalRenderV2=render;
render=function(){originalRenderV2();for(const el of document.querySelectorAll('.flow-card small'))if(el.textContent.includes('통합·주제'))el.textContent='지역·연합 게시판, HOT과 연령 필터';};
